def solve(intervals):
    if not intervals:
        return []
    ivs = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = [list(ivs[0])]
    for start, end in ivs[1:]:
        if start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

