    # Length of longest strictly increasing subsequence
    if not nums:
        return 0
    import bisect
    tails = []  # tails[i] = smallest tail of an increasing subseq of length i+1
    for x in nums:
        # find insertion point
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)
